def add_project(**_extra):
    import json, os, datetime, random, string, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _req_id():
        return "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")

    def _log(endpoint, account_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        logs.append({
            "id": _req_id(),
            "endpoint": endpoint,
            "account_id": account_id,
            "status": status,
            "error_code": error_code,
            "error_message": message,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    def _parse_body():
        body = _extra.get("body")
        if body is None:
            body = _extra.get("data")
        if body is None:
            body = _extra.get("request")
        if body is None:
            body = _extra
        if isinstance(body, str):
            try:
                body = json.loads(body)
            except Exception:
                return None, _err("VALIDATION_ERROR", "Request body must be a JSON object.")
        if not isinstance(body, dict):
            return None, _err("VALIDATION_ERROR", "Request body must be a JSON object.")
        return body, None

    def _pick_account(explicit_account_id=None):
        accounts = _load("todoist_accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        if isinstance(explicit_account_id, str) and explicit_account_id.strip():
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == explicit_account_id.strip() and a.get("status") == "active":
                    return a
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str):
                return a
        return None

    def _gen_id(prefix):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%y%m%d%H%M%S%f")
        rnd = "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(12))
        return f"{prefix}{ts}{rnd}"

    body, perr = _parse_body()
    if perr:
        _log("add-project", None, "error", perr["error"]["code"], perr["error"]["message"])
        return perr

    account_id = body.get("account_id")
    acct = _pick_account(account_id)
    if acct is None:
        _log("add-project", account_id if isinstance(account_id, str) else None, "error", "UNAUTHORIZED", "No active Todoist account connection is available for this request.")
        return _err("UNAUTHORIZED", "No active Todoist account connection is available for this request.", account_id=account_id)

    name = body.get("name")
    if not isinstance(name, str) or not name.strip():
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "name must be a non-empty string.")
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")

    color = body.get("color")
    if color is not None and not isinstance(color, str):
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "color must be a string or null.")
        return _err("VALIDATION_ERROR", "color must be a string or null.", field="color")

    parent_project_id = body.get("parent_project_id")
    if parent_project_id is not None and not isinstance(parent_project_id, str):
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "parent_project_id must be a string or null.")
        return _err("VALIDATION_ERROR", "parent_project_id must be a string or null.", field="parent_project_id")

    is_favorite = body.get("is_favorite", False)
    if not isinstance(is_favorite, bool):
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "is_favorite must be a boolean.")
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean.", field="is_favorite")

    inbox_project = body.get("inbox_project", False)
    if not isinstance(inbox_project, bool):
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "inbox_project must be a boolean.")
        return _err("VALIDATION_ERROR", "inbox_project must be a boolean.", field="inbox_project")

    view_style = body.get("view_style")
    if view_style is not None and view_style not in ("list", "board"):
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "view_style must be 'list', 'board', or null.")
        return _err("VALIDATION_ERROR", "view_style must be 'list', 'board', or null.", field="view_style")

    sort_order = body.get("sort_order")
    if sort_order is not None:
        if not isinstance(sort_order, int) or sort_order < 0:
            _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "sort_order must be an integer >= 0 or null.")
            return _err("VALIDATION_ERROR", "sort_order must be an integer >= 0 or null.", field="sort_order")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    if parent_project_id is not None:
        parent = next((p for p in projects if isinstance(p, dict) and p.get("id") == parent_project_id and p.get("account_id") == acct["id"]), None)
        if not parent or parent.get("status") == "deleted":
            _log("add-project", acct.get("id"), "error", "NOT_FOUND", "parent_project_id does not reference an existing non-deleted project for this account.")
            return _err("NOT_FOUND", "parent_project_id does not reference an existing non-deleted project for this account.", field="parent_project_id", parent_project_id=parent_project_id)

    todoist_project_id = body.get("todoist_project_id")
    if todoist_project_id is None:
        todoist_project_id = "tdstprj_" + _gen_id("")
    if not isinstance(todoist_project_id, str) or not todoist_project_id.strip():
        _log("add-project", acct.get("id"), "error", "VALIDATION_ERROR", "todoist_project_id must be a non-empty string when provided.")
        return _err("VALIDATION_ERROR", "todoist_project_id must be a non-empty string when provided.", field="todoist_project_id")

    # unique(account_id, todoist_project_id)
    if any(isinstance(p, dict) and p.get("account_id") == acct["id"] and p.get("todoist_project_id") == todoist_project_id for p in projects):
        _log("add-project", acct.get("id"), "error", "CONFLICT", "A project with this todoist_project_id already exists for this account.")
        return _err("CONFLICT", "A project with this todoist_project_id already exists for this account.", todoist_project_id=todoist_project_id)

    now = _now_iso()
    row = {
        "id": "tdprj_" + _gen_id(""),
        "account_id": acct["id"],
        "todoist_project_id": todoist_project_id,
        "name": name.strip(),
        "color": color,
        "parent_project_id": parent_project_id,
        "is_favorite": bool(is_favorite),
        "view_style": view_style,
        "inbox_project": bool(inbox_project),
        "sort_order": sort_order,
        "status": "active",
        "last_todoist_synced_at": now,
        "created_at": now,
        "updated_at": now
    }
    projects.append(row)
    _save("projects.json", projects)

    _log("add-project", acct.get("id"), "success", None, None)
    return {"project": row}

def get_projects(**_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, account_id=None, error_code=None):
        req_files = ["request_logs.json", "requests.json", "audit_logs.json", "usage.json"]
        payload = {
            "id": "req_" + uuid.uuid4().hex,
            "service": "todoist",
            "endpoint": "get-projects",
            "method": "GET",
            "account_id": account_id,
            "credential_id": account_id,
            "status": status,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        for fn in req_files:
            p = os.path.join(_DB, fn)
            if os.path.exists(p):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(payload)
                _save(fn, data)
                break

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated Todoist account context available.")

    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("status") == "active":
            acct = a
            break
    if not acct:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active Todoist account connection available for this operation.")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    rows = [p for p in projects if isinstance(p, dict) and p.get("account_id") == acct.get("id")]
    _log("ok", acct.get("id"))
    return {
        "projects": rows,
        "total": len(rows),
    }

