def delete_project(**_extra):
    import json, os, datetime, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _req_id():
        return "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
    def _log(account_id, status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        logs.append({
            "id": _req_id(),
            "endpoint": "delete-project",
            "account_id": account_id,
            "status": status,
            "error_code": error_code,
            "error_message": message,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    def _parse_body():
        body = _extra.get("body")
        if body is None:
            body = _extra.get("data")
        if body is None:
            body = _extra.get("request")
        if body is None:
            body = _extra
        if isinstance(body, str):
            try:
                body = json.loads(body)
            except Exception:
                return None, _err("VALIDATION_ERROR", "Request body must be a JSON object.")
        if not isinstance(body, dict):
            return None, _err("VALIDATION_ERROR", "Request body must be a JSON object.")
        return body, None

    def _pick_account(explicit_account_id=None):
        accounts = _load("todoist_accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        if isinstance(explicit_account_id, str) and explicit_account_id.strip():
            for a in accounts:
                if isinstance(a, dict) and a.get("id") == explicit_account_id.strip() and a.get("status") == "active":
                    return a
            return None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active" and isinstance(a.get("id"), str):
                return a
        return None

    body, perr = _parse_body()
    if perr:
        _log(None, "error", perr["error"]["code"], perr["error"]["message"])
        return perr

    account_id = body.get("account_id")
    project_id = body.get("project_id")

    acct = _pick_account(account_id)
    if acct is None:
        _log(account_id if isinstance(account_id, str) else None, "error", "UNAUTHORIZED", "No active Todoist account connection is available for this request.")
        return _err("UNAUTHORIZED", "No active Todoist account connection is available for this request.", account_id=account_id)

    if not isinstance(project_id, str) or not project_id.strip():
        _log(acct.get("id"), "error", "VALIDATION_ERROR", "project_id must be a non-empty string.")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string.", field="project_id")

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []

    idx = next((i for i, p in enumerate(projects) if isinstance(p, dict) and p.get("id") == project_id and p.get("account_id") == acct["id"]), None)
    if idx is None:
        _log(acct.get("id"), "error", "NOT_FOUND", "Project not found for this account.")
        return _err("NOT_FOUND", "Project not found for this account.", project_id=project_id)

    if projects[idx].get("status") == "deleted":
        _log(acct.get("id"), "error", "CONFLICT", "Project is already deleted.")
        return _err("CONFLICT", "Project is already deleted.", project_id=project_id)

    now = _now_iso()
    projects[idx]["status"] = "deleted"
    projects[idx]["updated_at"] = now
    _save("projects.json", projects)

    _log(acct.get("id"), "success", None, None)
    return {"project": projects[idx], "deleted": True}

def get_project_collaborators(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request logging / quotas (best-effort; schema doesn't provide a log collection)
    def _log(status_code, credential_id=None, message=None):
        # If a request log collection exists, write to it; otherwise no-op.
        # Common names to probe:
        for fname in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": "get-project-collaborators",
                    "credential_id": credential_id,
                    "status": status_code,
                    "message": message,
                    "latency_ms": int((time.time() - started) * 1000),
                    "created_at": ts
                })
                _save(fname, rows)
                break

    try:
        # Vendor tool signature provides no params; accept project id from runtime context.
        project_id = _extra.get("project_id") or _extra.get("id")
        if not isinstance(project_id, str) or not project_id.strip():
            _log("VALIDATION_ERROR", message="Missing or malformed project_id in runtime context.")
            return _err("VALIDATION_ERROR", "project_id is required")

        accounts = _load("todoist_accounts.json")
        if not isinstance(accounts, list):
            accounts = []

        # Ambient auth: find any account that can serve the call (active token).
        # The store doesn't have raw token, only hashes; therefore "token validity"
        # here is based on account.status.
        account = None
        for a in accounts:
            if isinstance(a, dict) and a.get("status") == "active":
                account = a
                break
        if not account:
            _log("UNAUTHORIZED", message="No active Todoist account connection available.")
            return _err("UNAUTHORIZED", "No active Todoist account connection is available")

        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []

        project = None
        for p in projects:
            if isinstance(p, dict) and p.get("id") == project_id and p.get("account_id") == account.get("id"):
                project = p
                break

        if not project or project.get("status") == "deleted":
            _log("NOT_FOUND", credential_id=account.get("id"), message="Project not found for account.")
            return _err("NOT_FOUND", "Project not found")

        # Business rule indicates this is served by calling Todoist and may be cached.
        # No collaborators collection is declared in schema, so return empty list as mirror state.
        # Do not fabricate collaborators.
        resp = {
            "project_id": project_id,
            "todoist_project_id": project.get("todoist_project_id"),
            "collaborators": []
        }
        _log("OK", credential_id=account.get("id"))
        return resp
    except Exception as e:
        _log("ERROR", message=str(e))
        return _err("CONFLICT", "Unexpected error", detail=str(e))

