    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("bad datetime")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"tdreq_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get-task",
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(account_id, str) or not account_id.strip():
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id is required and must be a non-empty string", field="account_id")
        if not isinstance(task_id, str) or not task_id.strip():
            _log("error", "VALIDATION_ERROR")
