            "id": f"tdreq_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "get-tasks",
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        })
        _save("request_logs.json", logs)

    def _decode_cursor(c):
