            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                raise ValueError("cursor")
            return obj
        except Exception:
            raise ValueError("cursor")

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    try:
        if not isinstance(account_id, str) or not account_id.strip() or not account_id.startswith("tdacct_"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "account_id is required and must be a valid ULID", field="account_id")

        if project_id is not None:
            if not isinstance(project_id, str) or not project_id.startswith("tdprj_"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "project_id is malformed", field="project_id")
        if section_id is not None:
            if not isinstance(section_id, str) or not section_id.startswith("tdsec_"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "section_id is malformed", field="section_id")
        if parent_task_id is not None:
            if not isinstance(parent_task_id, str) or not parent_task_id.startswith("tdtsk_"):
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "parent_task_id is malformed", field="parent_task_id")
        if label is not None and (not isinstance(label, str) or not label.strip()):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "label must be a non-empty string", field="label")
        if status is not None and status not in ("active", "completed", "deleted"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "completed", "deleted"])

        due_from_dt = _parse_dt(due_from, "due_from")
        due_to_dt = _parse_dt(due_to, "due_to")
        completed_from_dt = _parse_dt(completed_from, "completed_from")
        completed_to_dt = _parse_dt(completed_to, "completed_to")

        if due_from_dt and due_to_dt and due_from_dt > due_to_dt:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "due_from must be <= due_to")
        if completed_from_dt and completed_to_dt and completed_from_dt > completed_to_dt:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "completed_from must be <= completed_to")

        if sort_by is None:
            sort_by = "created_at"
        if sort_by not in ("created_at", "updated_at", "due_date", "completed_at", "priority", "order"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_by", field="sort_by")
        if sort_order is None:
            sort_order = "asc"
        if sort_order not in ("asc", "desc"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid sort_order", field="sort_order")

        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

        # Authenticate ambient context
        accounts = _load("todoist_accounts.json")
        if not isinstance(accounts, list):
            accounts = []
        acct = next((a for a in accounts if a.get("id") == account_id), None)
        if not acct or acct.get("status") != "active":
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Todoist account token is missing/invalid or not active")

        # FK integrity checks for provided filters
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        sections = _load("sections.json")
        if not isinstance(sections, list):
            sections = []
        tasks = _load("tasks.json")
        if not isinstance(tasks, list):
            tasks = []

        if project_id is not None:
            prj = next((p for p in projects if p.get("id") == project_id and p.get("account_id") == account_id), None)
            if not prj or prj.get("status") == "deleted":
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Referenced project not found", field="project_id")
        if section_id is not None:
            sec = next((s for s in sections if s.get("id") == section_id and s.get("account_id") == account_id), None)
            if not sec or sec.get("status") == "deleted":
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Referenced section not found", field="section_id")
            # section must reference non-deleted project
            sec_prj = next((p for p in projects if p.get("id") == sec.get("project_id") and p.get("account_id") == account_id), None)
            if not sec_prj or sec_prj.get("status") == "deleted":
                _log("error", "CONFLICT")
                return _err("CONFLICT", "Section references a missing/deleted project", field="section_id")
            if project_id is not None and sec.get("project_id") != project_id:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "section_id does not belong to the specified project_id")
        if parent_task_id is not None:
            pt = next((t for t in tasks if t.get("id") == parent_task_id and t.get("account_id") == account_id), None)
            if not pt or pt.get("status") == "deleted":
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Referenced parent task not found", field="parent_task_id")

        # Apply filters scoped to account
        def _dt_from_row(v):
            if v is None:
                return None
            if isinstance(v, str) and v:
                ss = v
                if ss.endswith("Z"):
                    ss = ss[:-1] + "+00:00"
                try:
                    return datetime.datetime.fromisoformat(ss)
                except Exception:
                    return None
            return None

        label_norm = label.strip().casefold() if isinstance(label, str) else None

        rows = [t for t in tasks if t.get("account_id") == account_id]

        if project_id is not None:
            rows = [t for t in rows if t.get("project_id") == project_id]
        if section_id is not None:
            rows = [t for t in rows if t.get("section_id") == section_id]
        if parent_task_id is not None:
            rows = [t for t in rows if t.get("parent_task_id") == parent_task_id]
        if status is not None:
            rows = [t for t in rows if t.get("status") == status]
        if label_norm is not None:
            def _has_label(t):
                labs = t.get("labels")
                if not isinstance(labs, list):
                    return False
                for x in labs:
                    if isinstance(x, str) and x.casefold() == label_norm:
                        return True
                return False
            rows = [t for t in rows if _has_label(t)]

        if due_from_dt or due_to_dt:
            tmp = []
            for t in rows:
                d = _dt_from_row(t.get("due_date"))
                if d is None:
                    continue
                if due_from_dt and d < due_from_dt:
                    continue
                if due_to_dt and d > due_to_dt:
                    continue
                tmp.append(t)
            rows = tmp

        if completed_from_dt or completed_to_dt:
            tmp = []
            for t in rows:
                c = _dt_from_row(t.get("completed_at"))
                if c is None:
                    continue
                if completed_from_dt and c < completed_from_dt:
                    continue
                if completed_to_dt and c > completed_to_dt:
                    continue
                tmp.append(t)
            rows = tmp

        # Sorting
        def _sort_key(t):
            v = t.get(sort_by)
            if sort_by in ("created_at", "updated_at", "due_date", "completed_at"):
                dt = _dt_from_row(v)
                return dt if dt is not None else (datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
            if sort_by in ("priority", "order"):
                return v if isinstance(v, int) else -10**18
            return v

        reverse = (sort_order == "desc")
        rows.sort(key=_sort_key, reverse=reverse)

        # Pagination via cursor offset over the filtered+sorted set
        offset = 0
        if cursor:
            cur = _decode_cursor(cursor)
            if cur.get("account_id") != account_id or cur.get("endpoint") != "get-tasks":
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is not valid for this request", field="cursor")
            if not isinstance(cur.get("offset"), int) or cur["offset"] < 0:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is malformed", field="cursor")
            offset = cur["offset"]

        total = len(rows)
        page = rows[offset:offset + limit]
        next_cursor = None
        if offset + limit < total:
            next_cursor = _encode_cursor({"endpoint": "get-tasks", "account_id": account_id, "offset": offset + limit})

        _log("ok", None)
        return {
            "tasks": page,
            "meta": {
                "total": total,
                "limit": limit,
                "has_more": (next_cursor is not None),
                "next_cursor": next_cursor
            }
        }
    except ValueError as ve:
        field = str(ve)
        _log("error", "VALIDATION_ERROR")
        if field in ("due_from", "due_to", "completed_from", "completed_to", "cursor"):
            return _err("VALIDATION_ERROR", f"Invalid {field} format", field=field)
        return _err("VALIDATION_ERROR", "Invalid input")
    except Exception as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Request could not be processed", detail=str(e))

