def get_productivity_stats(account_id, from_, to, group_by, project_id=None, label=None, **_extra):
    from_ = _extra.pop("from", from_)
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = datetime.datetime.utcnow()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                # datetime.fromisoformat doesn't accept 'Z' in older versions
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                # Treat naive as UTC to keep deterministic behavior
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except ValueError:
            return None

    def _dt_to_utc(dt):
        if dt.tzinfo is None:
            return dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _bucket_start(dt_utc, gb):
        # dt_utc is aware UTC
        d = dt_utc.date()
        if gb == "day":
            return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)
        if gb == "week":
            # ISO week starts Monday
            start = d - datetime.timedelta(days=d.weekday())
            return datetime.datetime(start.year, start.month, start.day, tzinfo=datetime.timezone.utc)
        if gb == "month":
            return datetime.datetime(d.year, d.month, 1, tzinfo=datetime.timezone.utc)
        return None

    def _next_bucket_start(bucket_dt_utc, gb):
        if gb == "day":
            return bucket_dt_utc + datetime.timedelta(days=1)
        if gb == "week":
            return bucket_dt_utc + datetime.timedelta(days=7)
        if gb == "month":
            y, m = bucket_dt_utc.year, bucket_dt_utc.month
            if m == 12:
                return datetime.datetime(y + 1, 1, 1, tzinfo=datetime.timezone.utc)
            return datetime.datetime(y, m + 1, 1, tzinfo=datetime.timezone.utc)
        return None

    def _iso_bucket(dt_utc):
        # return ISO string with Z
        return dt_utc.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # ---- Request logging with rate/quota enforcement (best-effort, offline) ----
    # Schema didn't declare request logs. If a log file exists, we will use it.
    log_candidates = [
        "request_logs.json", "requests.json", "usage.json", "audit_logs.json", "audit.json"
    ]
    log_file = None
    for fn in log_candidates:
        if os.path.exists(os.path.join(_DB, fn)):
            log_file = fn
            break

    logs = _load(log_file) if log_file else None

    def _log(status, error_code=None):
        if not log_file:
            return
        try:
            t1 = datetime.datetime.utcnow()
            ms = int((t1 - _t0).total_seconds() * 1000)
            row = {
                "id": f"req_{int(t1.timestamp()*1000)}",
                "endpoint": "get-productivity-stats",
                "account_id": account_id,
                "status": status,
                "error_code": error_code,
                "latency_ms": ms,
                "ts": _iso_now(),
            }
            if isinstance(logs, list):
                logs.append(row)
                _save(log_file, logs)
        except Exception:
            # Do not fail the main request due to logging issues
            pass

    def _rate_limit_check():
        if not log_file or not isinstance(logs, list):
            return None
        # Simple local limit: 120 requests/min per account_id
        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        window = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in reversed(logs[-2000:]):
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = r.get("ts")
            dt = _parse_dt(ts) if isinstance(ts, str) else None
            if dt is None:
                continue
            dt = _dt_to_utc(dt)
            if dt < window:
                continue
            cnt += 1
            if cnt >= 120:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("error", "RATE_LIMIT")
        return rl

    # ---- Input validation ----
    if not isinstance(account_id, str) or not account_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string")

    if group_by not in ("day", "week", "month"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "group_by must be one of: day, week, month", allowed=["day", "week", "month"])

    dt_from = _parse_dt(from_)
    dt_to = _parse_dt(to)
    if dt_from is None or dt_to is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from/to must be valid RFC3339/ISO date-time strings")

    dt_from = _dt_to_utc(dt_from)
    dt_to = _dt_to_utc(dt_to)

    if dt_from > dt_to:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "from must be <= to")

    if project_id is not None and (not isinstance(project_id, str) or not project_id.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string when provided")

    if label is not None and (not isinstance(label, str) or not label.strip()):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided")

    label_norm = label.strip().casefold() if isinstance(label, str) else None

    # ---- Auth / scoping ----
    accounts = _load("todoist_accounts.json")
    acct = None
    if isinstance(accounts, list):
        for a in accounts:
            if isinstance(a, dict) and a.get("id") == account_id:
                acct = a
                break
    if not acct:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Todoist account not found", account_id=account_id)

    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Todoist account is not active", status=acct.get("status"))

    # ---- FK integrity for project filter ----
    if project_id is not None:
        projects = _load("projects.json")
        prj = None
        if isinstance(projects, list):
            for p in projects:
                if isinstance(p, dict) and p.get("id") == project_id and p.get("account_id") == account_id:
                    prj = p
                    break
        if not prj or prj.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Project not found (or deleted) for this account", project_id=project_id)

    # ---- Compute stats ----
    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    # Prepare buckets for full requested range (inclusive)
    start_bucket = _bucket_start(dt_from, group_by)
    end_bucket = _bucket_start(dt_to, group_by)
    if start_bucket is None or end_bucket is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid group_by")

    buckets = {}
    b = start_bucket
    # include buckets up to and including end_bucket
    while b <= end_bucket:
        buckets[_iso_bucket(b)] = 0
        nb = _next_bucket_start(b, group_by)
        if nb is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid group_by")
        b = nb

    # Only tasks with status='completed' and non-NULL completed_at count
    for t in tasks:
        if not isinstance(t, dict):
            continue
        if t.get("account_id") != account_id:
            continue
        if t.get("status") != "completed":
            continue
        comp = t.get("completed_at")
        dtc = _parse_dt(comp) if isinstance(comp, str) else None
        if dtc is None:
            # Exclude tasks without completed_at (rule)
            continue
        dtc = _dt_to_utc(dtc)
        if dtc < dt_from or dtc > dt_to:
            continue

        if project_id is not None:
            if t.get("project_id") != project_id:
                continue

        if label_norm is not None:
            labs = t.get("labels")
            if not isinstance(labs, list):
                continue
            found = False
            for ln in labs:
                if isinstance(ln, str) and ln.strip().casefold() == label_norm:
                    found = True
                    break
            if not found:
                continue

        bk = _bucket_start(dtc, group_by)
        if bk is None:
            continue
        k = _iso_bucket(bk)
        if k in buckets:
            buckets[k] += 1

    # Response shape: buckets with timestamps + counts, plus metadata
    out = []
    for k in sorted(buckets.keys()):
        out.append({"bucket_start": k, "completed_count": buckets[k]})

    resp = {
        "account_id": account_id,
        "from": _iso_bucket(_bucket_start(dt_from, "day")) if False else (dt_from.replace(microsecond=0).isoformat().replace("+00:00", "Z")),
        "to": (dt_to.replace(microsecond=0).isoformat().replace("+00:00", "Z")),
        "group_by": group_by,
        "filters": {
            "project_id": project_id,
            "label": label
        },
        "buckets": out
    }

    _log("ok", None)
    return resp

