    if labels is not None:
        if not isinstance(labels, list) or any((not isinstance(x, str) or not x.strip()) for x in labels):
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "labels must be an array of non-empty strings."))
    if duration_amount is not None:
        if not isinstance(duration_amount, int) or duration_amount < 1:
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "duration_amount must be an integer >= 1 when provided."))
    if duration_unit is not None:
        if duration_unit not in ("minute", "day"):
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "duration_unit must be one of: minute, day."))
    if due_timezone is not None and not isinstance(due_timezone, str):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "due_timezone must be a string when provided."))
    if due_lang is not None and not isinstance(due_lang, str):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "due_lang must be a string when provided."))

    def _parse_dt_or_none(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "INVALID"
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        except Exception:
            return "INVALID"

    if due_date is not None:
        dd = _parse_dt_or_none(due_date)
        if dd == "INVALID":
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "due_date must be an ISO 8601 datetime string or null."))
    if deadline_date is not None:
        dl = _parse_dt_or_none(deadline_date)
        if dl == "INVALID":
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "deadline_date must be an ISO 8601 datetime string or null."))

    # Account existence and active
    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        status, code = "error", "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Account not found.", account_id=account_id))
    if acct.get("status") != "active":
        status, code = "error", "UNAUTHORIZED"
        return _log_and_return(_err("UNAUTHORIZED", "Account is not active for this operation.", account_status=acct.get("status")))

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    idx = None
    for i, t in enumerate(tasks):
        if t.get("id") == task_id and t.get("account_id") == account_id:
            idx = i
            break
    if idx is None:
        status, code = "error", "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Task not found.", task_id=task_id))

    task = tasks[idx]
    if task.get("status") == "deleted":
        status, code = "error", "CONFLICT"
        return _log_and_return(_err("CONFLICT", "Cannot update a deleted task.", task_id=task_id))

    # Ensure FK integrity if task currently references deleted project/section; (do not auto-fix here)
    if task.get("project_id") is not None:
        projects = _load("projects.json")
        if not isinstance(projects, list):
            projects = []
        prj = next((p for p in projects if p.get("id") == task.get("project_id") and p.get("account_id") == account_id), None)
        if not prj or prj.get("status") == "deleted":
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "Task references a missing/deleted project.", project_id=task.get("project_id")))
    if task.get("section_id") is not None:
        sections = _load("sections.json")
        if not isinstance(sections, list):
            sections = []
        sec = next((s for s in sections if s.get("id") == task.get("section_id") and s.get("account_id") == account_id), None)
        if not sec or sec.get("status") == "deleted":
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "Task references a missing/deleted section.", section_id=task.get("section_id")))

    # Handle labels: ensure labels rows exist; normalize case-insensitive canonical form
    labels_store = _load("labels.json")
    if not isinstance(labels_store, list):
        labels_store = []

    def _canon_label(s):
        # canonical form: strip and keep original casing of first seen active label; else title-ish fallback
        return s.strip()

    def _find_active_label_by_norm(norm):
        for row in labels_store:
            if row.get("account_id") != account_id:
                continue
            if row.get("status") != "active":
                continue
            nm = row.get("name")
            if isinstance(nm, str) and nm.strip().casefold() == norm:
                return row
        return None

    def _gen_id(prefix):
        # deterministic enough offline
        return prefix + "_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")

    if labels is not None:
        new_task_labels = []
        seen = set()
        for raw in labels:
            canon = _canon_label(raw)
            norm = canon.casefold()
            if norm in seen:
                continue
            seen.add(norm)
            existing = _find_active_label_by_norm(norm)
            if existing is None:
                # create new label row (is_shared=false by default)
                now = datetime.datetime.now(datetime.timezone.utc).isoformat()
                new_row = {
                    "id": _gen_id("tdlbl"),
                    "account_id": account_id,
                    "todoist_label_id": None,
                    "name": canon,
                    "color": None,
                    "is_favorite": False,
                    "is_shared": False,
                    "status": "active",
                    "created_at": now,
                    "updated_at": now
                }
                # enforce unique(active) by norm (already checked), insert
                labels_store.append(new_row)
                existing = new_row
            # store canonical name from row to keep stable
            new_task_labels.append(existing.get("name"))
        task["labels"] = new_task_labels

    # Apply scalar updates
    if content is not None:
        task["content"] = content
    if description is not None:
        task["description"] = description
    if priority is not None:
        task["priority"] = priority
    if due_date is not None:
        task["due_date"] = _parse_dt_or_none(due_date)
    if due_timezone is not None:
        task["due_timezone"] = due_timezone
    if due_lang is not None:
        task["due_lang"] = due_lang
    if deadline_date is not None:
        task["deadline_date"] = _parse_dt_or_none(deadline_date)
    if duration_amount is not None:
        task["duration_amount"] = duration_amount
    if duration_unit is not None:
        task["duration_unit"] = duration_unit

    # Cross-field constraints
    if task.get("content") is None or (isinstance(task.get("content"), str) and task.get("content").strip() == ""):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "content cannot be empty."))
    pr = task.get("priority")
    if not isinstance(pr, int) or pr < 1 or pr > 4:
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "priority must be between 1 and 4."))
    da = task.get("duration_amount")
    if da is not None and (not isinstance(da, int) or da <= 0):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "duration_amount must be > 0 when set."))
    du = task.get("duration_unit")
    if du is not None and du not in ("minute", "day"):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "duration_unit must be 'minute' or 'day' when set."))
    if task.get("completed_at") is None and task.get("status") == "completed":
        status, code = "error", "CONFLICT"
        return _log_and_return(_err("CONFLICT", "completed tasks must have completed_at."))
    if task.get("completed_at") is not None and task.get("status") != "completed":
        # allow update-task to clear completed_at only via reopen-task; treat as conflict
        status, code = "error", "CONFLICT"
        return _log_and_return(_err("CONFLICT", "completed_at must be null unless status='completed'."))

    # Persist changes
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()
    task["updated_at"] = now_iso
    tasks[idx] = task
    _save("tasks.json", tasks)
    if labels is not None:
        _save("labels.json", labels_store)

    return _log_and_return({"task": task})

def close_task(account_id, task_id, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _req_id():
        return "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
    def _log(status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        logs.append({
            "id": _req_id(),
            "endpoint": "close-task",
            "account_id": account_id if isinstance(account_id, str) else None,
            "status": status,
            "error_code": error_code,
            "error_message": message,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    if not isinstance(account_id, str) or not re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id or ""):
        _log("error", "VALIDATION_ERROR", "account_id is invalid.")
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")
    if not isinstance(task_id, str) or not re.match(r"^tdtsk_[0-9A-Z]{2,}$", task_id or ""):
        _log("error", "VALIDATION_ERROR", "task_id is invalid.")
        return _err("VALIDATION_ERROR", "task_id is invalid.", field="task_id")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _log("error", "UNAUTHORIZED", "No active Todoist account connection is available for this account_id.")
        return _err("UNAUTHORIZED", "No active Todoist account connection is available for this account_id.", account_id=account_id)

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    idx = next((i for i, t in enumerate(tasks) if isinstance(t, dict) and t.get("id") == task_id and t.get("account_id") == account_id), None)
    if idx is None:
        _log("error", "NOT_FOUND", "Task not found for this account.")
        return _err("NOT_FOUND", "Task not found for this account.", task_id=task_id)

    cur_status = tasks[idx].get("status")
    if cur_status == "deleted":
        _log("error", "INVALID_TRANSITION", "It is invalid to close a deleted task.")
        return _err("INVALID_TRANSITION", "It is invalid to close a deleted task.", task_id=task_id, from_status="deleted", to_status="completed")
    if cur_status == "completed":
        _log("error", "CONFLICT", "Task is already completed.")
        return _err("CONFLICT", "Task is already completed.", task_id=task_id)

    now = _now_iso()
    tasks[idx]["status"] = "completed"
    tasks[idx]["completed_at"] = now
    tasks[idx]["updated_at"] = now
    _save("tasks.json", tasks)

    _log("success", None, None)
    return {"task": tasks[idx]}

def move_tasks(account_id, task_ids, project_id=None, section_id=None, parent_task_id=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    status = "success"
    code = None
    used_cred = None

    def _log_and_return(payload):
        nonlocal status, code
        t1 = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = int((t1 - t0).total_seconds() * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + t1.strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "move-tasks",
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential": used_cred,
            "status": status,
            "error_code": code,
            "latency_ms": latency_ms,
            "ts": t1.isoformat()
        })
        _save("request_logs.json", logs)
        return payload

    # Rate limit
    try:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[::-1]:
            try:
                ts = datetime.datetime.fromisoformat(r.get("ts"))
                if ts.tzinfo is None:
                    ts = ts.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if ts < window_start:
                break
            if r.get("endpoint") and r.get("account_id") == account_id:
                cnt += 1
        if cnt >= 120:
            status, code = "error", "RATE_LIMIT"
            return _log_and_return(_err("RATE_LIMIT", "Rate limit exceeded. Please retry later."))
    except Exception:
        pass

    if not isinstance(account_id, str) or not account_id:
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "account_id must be a non-empty string."))
    if not isinstance(task_ids, list) or len(task_ids) < 1 or any((not isinstance(t, str) or not t) for t in task_ids):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "task_ids must be a non-empty array of task id strings."))
    if project_id is None and section_id is None and parent_task_id is None:
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "At least one destination must be provided: project_id, section_id, or parent_task_id."))

    if project_id is not None and (not isinstance(project_id, str) or not project_id):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "project_id must be a non-empty string when provided."))
    if section_id is not None and (not isinstance(section_id, str) or not section_id):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "section_id must be a non-empty string when provided."))
    if parent_task_id is not None and (not isinstance(parent_task_id, str) or not parent_task_id):
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "parent_task_id must be a non-empty string when provided."))

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        status, code = "error", "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "Account not found.", account_id=account_id))
    if acct.get("status") != "active":
        status, code = "error", "UNAUTHORIZED"
        return _log_and_return(_err("UNAUTHORIZED", "Account is not active for this operation.", account_status=acct.get("status")))

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    # Resolve destination project/section/parent with FK rules and account scoping
    dest_project = None
    dest_section = None
    dest_parent = None

    if project_id is not None:
        dest_project = next((p for p in projects if p.get("id") == project_id and p.get("account_id") == account_id), None)
        if not dest_project or dest_project.get("status") == "deleted":
            status, code = "error", "NOT_FOUND"
            return _log_and_return(_err("NOT_FOUND", "Destination project not found.", project_id=project_id))

    if section_id is not None:
        dest_section = next((s for s in sections if s.get("id") == section_id and s.get("account_id") == account_id), None)
        if not dest_section or dest_section.get("status") == "deleted":
            status, code = "error", "NOT_FOUND"
            return _log_and_return(_err("NOT_FOUND", "Destination section not found.", section_id=section_id))
        # section implies a project
        sec_project_id = dest_section.get("project_id")
        if not isinstance(sec_project_id, str) or not sec_project_id:
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "Destination section is missing a project_id.", section_id=section_id))
        sec_project = next((p for p in projects if p.get("id") == sec_project_id and p.get("account_id") == account_id), None)
        if not sec_project or sec_project.get("status") == "deleted":
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "Destination section references a missing/deleted project.", project_id=sec_project_id))
        # If project_id provided, must match section's project
        if dest_project is not None and dest_project.get("id") != sec_project_id:
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "section_id must belong to the provided destination project_id.", section_project_id=sec_project_id, project_id=project_id))
        dest_project = sec_project

    if parent_task_id is not None:
        dest_parent = next((t for t in tasks if t.get("id") == parent_task_id and t.get("account_id") == account_id), None)
        if not dest_parent:
            status, code = "error", "NOT_FOUND"
            return _log_and_return(_err("NOT_FOUND", "Destination parent task not found.", parent_task_id=parent_task_id))
        if dest_parent.get("status") == "deleted":
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "Cannot move under a deleted parent task.", parent_task_id=parent_task_id))
        # parent implies project (and optionally section)
        parent_project_id = dest_parent.get("project_id")
        if parent_project_id is not None:
            pp = next((p for p in projects if p.get("id") == parent_project_id and p.get("account_id") == account_id), None)
            if not pp or pp.get("status") == "deleted":
                status, code = "error", "CONFLICT"
                return _log_and_return(_err("CONFLICT", "Parent task references a missing/deleted project.", project_id=parent_project_id))
        # If destination project is explicitly provided, it must match parent project if parent has one
        if dest_project is not None and parent_project_id is not None and dest_project.get("id") != parent_project_id:
            status, code = "error", "VALIDATION_ERROR"
            return _log_and_return(_err("VALIDATION_ERROR", "parent_task_id must be within the destination project_id.", parent_project_id=parent_project_id, project_id=dest_project.get("id")))

        # If no dest_project is provided, inherit from parent (may be null)
        if dest_project is None and parent_project_id is not None:
            dest_project = next((p for p in projects if p.get("id") == parent_project_id and p.get("account_id") == account_id), None)

        # If a section_id is provided, parent should be in same project; already enforced via dest_project.
        # Do not force section inheritance; leave to rules: moving to different project clears section unless explicitly set.

    # Ensure all task_ids exist for this account (single-transaction semantics: all-or-nothing)
    unique_ids = []
    seen = set()
    for tid in task_ids:
        if tid in seen:
            continue
        seen.add(tid)
        unique_ids.append(tid)

    id_to_idx = {}
    for i, t in enumerate(tasks):
        if t.get("account_id") == account_id and t.get("id") in seen:
            id_to_idx[t.get("id")] = i
    missing = [tid for tid in unique_ids if tid not in id_to_idx]
    if missing:
        status, code = "error", "NOT_FOUND"
        return _log_and_return(_err("NOT_FOUND", "One or more tasks were not found.", missing_task_ids=missing))

    # Validate no self-parenting
    if parent_task_id is not None and parent_task_id in seen:
        status, code = "error", "VALIDATION_ERROR"
        return _log_and_return(_err("VALIDATION_ERROR", "A task cannot be moved to be a child of itself.", parent_task_id=parent_task_id))

    # Determine destination project change relative to each task; apply rule:
    # if moving to a different project, section_id must be NULL unless a section in that target project is explicitly set.
    moved = []
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Snapshot original values to enforce atomicity; we'll build new task objects first
    new_tasks = {}
    for tid, idx in id_to_idx.items():
        t = tasks[idx]
        if t.get("status") == "deleted":
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "Cannot move a deleted task.", task_id=tid))

        new_t = dict(t)

        # Compute target project for this task:
        target_project_id = new_t.get("project_id")
        if dest_project is not None:
            target_project_id = dest_project.get("id")
        # else leave as-is if not specified by section/parent/project

        # Apply section: if explicitly provided, set it; else if project changes, clear section
        if section_id is not None:
            # dest_section already validated and implies dest_project
            new_t["section_id"] = dest_section.get("id")
            new_t["project_id"] = dest_project.get("id") if dest_project is not None else new_t.get("project_id")
        else:
            # no section specified; if project_id specified (or implied) and differs, clear section
            original_project_id = t.get("project_id")
            if dest_project is not None and dest_project.get("id") != original_project_id:
                new_t["section_id"] = None
            # set project if provided/implied
            if dest_project is not None:
                new_t["project_id"] = dest_project.get("id")

        # Apply parent
        if parent_task_id is not None:
            new_t["parent_task_id"] = dest_parent.get("id")
            # parent implies project; ensure project alignment when parent has project
            if dest_parent.get("project_id") is not None:
                new_t["project_id"] = dest_parent.get("project_id")
                if section_id is None:
                    # if project changed due to parent and section not explicitly set, clear section
                    if t.get("project_id") != new_t.get("project_id"):
                        new_t["section_id"] = None
        # If parent not specified, leave parent as-is
        # But if moving across projects, having a parent in another project becomes invalid; clear parent in that case.
        if parent_task_id is None:
            if dest_project is not None and t.get("project_id") != dest_project.get("id"):
                new_t["parent_task_id"] = None

        # FK integrity: project_id non-null must reference non-deleted project
        if new_t.get("project_id") is not None:
            prj = next((p for p in projects if p.get("id") == new_t.get("project_id") and p.get("account_id") == account_id), None)
            if not prj or prj.get("status") == "deleted":
                status, code = "error", "CONFLICT"
                return _log_and_return(_err("CONFLICT", "Destination project is missing/deleted.", project_id=new_t.get("project_id"), task_id=tid))

        # FK integrity: section_id non-null must reference non-deleted section and must belong to same project
        if new_t.get("section_id") is not None:
            sec = next((s for s in sections if s.get("id") == new_t.get("section_id") and s.get("account_id") == account_id), None)
            if not sec or sec.get("status") == "deleted":
                status, code = "error", "CONFLICT"
                return _log_and_return(_err("CONFLICT", "Destination section is missing/deleted.", section_id=new_t.get("section_id"), task_id=tid))
            if new_t.get("project_id") is None or sec.get("project_id") != new_t.get("project_id"):
                status, code = "error", "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "section_id must belong to the task's project_id.", section_project_id=sec.get("project_id"), project_id=new_t.get("project_id"), task_id=tid))

        # FK integrity: parent_task_id non-null must reference non-deleted task; prevent self; prevent parent=itself
        if new_t.get("parent_task_id") is not None:
            if new_t.get("parent_task_id") == new_t.get("id"):
                status, code = "error", "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "parent_task_id cannot equal task id.", task_id=tid))
            pt = next((x for x in tasks if x.get("id") == new_t.get("parent_task_id") and x.get("account_id") == account_id), None)
            if not pt or pt.get("status") == "deleted":
                status, code = "error", "CONFLICT"
                return _log_and_return(_err("CONFLICT", "parent_task_id references missing/deleted task.", parent_task_id=new_t.get("parent_task_id"), task_id=tid))
            # If both have project_id, enforce match
            if pt.get("project_id") is not None and new_t.get("project_id") is not None and pt.get("project_id") != new_t.get("project_id"):
                status, code = "error", "VALIDATION_ERROR"
                return _log_and_return(_err("VALIDATION_ERROR", "Task and parent_task must be in the same project.", task_project_id=new_t.get("project_id"), parent_project_id=pt.get("project_id"), task_id=tid))

        # Constraint: section_id is null or project_id is not null
        if new_t.get("section_id") is not None and new_t.get("project_id") is None:
            status, code = "error", "CONFLICT"
            return _log_and_return(_err("CONFLICT", "section_id cannot be set when project_id is null.", task_id=tid))

        new_t["updated_at"] = now_iso
        new_tasks[tid] = new_t

    # Apply all changes atomically (single save at end)
    for tid, idx in id_to_idx.items():
        tasks[idx] = new_tasks[tid]
        moved.append(new_tasks[tid])

    _save("tasks.json", tasks)

    return _log_and_return({
        "account_id": account_id,
        "moved_count": len(moved),
        "tasks": moved,
        "destination": {
            "project_id": project_id,
            "section_id": section_id,
            "parent_task_id": parent_task_id
        }
    })

def delete_task(account_id, task_id, **_extra):
    import json, os, datetime, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    def _req_id():
        return "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
    def _log(status, error_code=None, message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((datetime.datetime.now(datetime.timezone.utc) - t0).total_seconds() * 1000)
        logs.append({
            "id": _req_id(),
            "endpoint": "delete-task",
            "account_id": account_id if isinstance(account_id, str) else None,
            "status": status,
            "error_code": error_code,
            "error_message": message,
            "latency_ms": latency_ms,
            "created_at": _now_iso()
        })
        _save("request_logs.json", logs)

    if not isinstance(account_id, str) or not re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id or ""):
        _log("error", "VALIDATION_ERROR", "account_id is invalid.")
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")
    if not isinstance(task_id, str) or not re.match(r"^tdtsk_[0-9A-Z]{2,}$", task_id or ""):
        _log("error", "VALIDATION_ERROR", "task_id is invalid.")
        return _err("VALIDATION_ERROR", "task_id is invalid.", field="task_id")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id and a.get("status") == "active"), None)
    if not acct:
        _log("error", "UNAUTHORIZED", "No active Todoist account connection is available for this account_id.")
        return _err("UNAUTHORIZED", "No active Todoist account connection is available for this account_id.", account_id=account_id)

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    idx = next((i for i, t in enumerate(tasks) if isinstance(t, dict) and t.get("id") == task_id and t.get("account_id") == account_id), None)
    if idx is None:
        _log("error", "NOT_FOUND", "Task not found for this account.")
        return _err("NOT_FOUND", "Task not found for this account.", task_id=task_id)

    if tasks[idx].get("status") == "deleted":
        _log("error", "CONFLICT", "Task is already deleted.")
        return _err("CONFLICT", "Task is already deleted.", task_id=task_id)

    now = _now_iso()
    tasks[idx]["status"] = "deleted"
    tasks[idx]["updated_at"] = now
    _save("tasks.json", tasks)

    _log("success", None, None)
    return {"task": tasks[idx], "deleted": True}

def reopen_task(account_id, task_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, meta=None, started=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = None
            if started is not None:
                latency_ms = int((time.time() - started) * 1000)
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "reopen-task",
                "account_id": account_id,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    started = time.time()

    if not isinstance(account_id, str) or not re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id or ""):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "account_id"}, started=started)
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")
    if not isinstance(task_id, str) or not re.match(r"^tdtsk_[0-9A-Z]{2,}$", task_id or ""):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "task_id"}, started=started)
        return _err("VALIDATION_ERROR", "task_id is invalid.", field="task_id")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", meta={"code": "NOT_FOUND", "entity": "todoist_accounts"}, started=started)
        return _err("NOT_FOUND", "Account not found.", entity="todoist_accounts", id=account_id)
    if acct.get("status") in ("revoked", "disabled"):
        _log("error", meta={"code": "UNAUTHORIZED"}, started=started)
        return _err("UNAUTHORIZED", "Account is not authorized for modifications in its current status.", account_status=acct.get("status"))

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    idx = None
    row = None
    for i, t in enumerate(tasks):
        if t.get("id") == task_id and t.get("account_id") == account_id:
            idx, row = i, t
            break
    if row is None:
        _log("error", meta={"code": "NOT_FOUND", "entity": "tasks"}, started=started)
        return _err("NOT_FOUND", "Task not found.", entity="tasks", id=task_id)

    # Business rule: invalid to reopen deleted
    if row.get("status") == "deleted":
        _log("error", meta={"code": "INVALID_TRANSITION", "from": "deleted", "to": "active"}, started=started)
        return _err("INVALID_TRANSITION", "Cannot reopen a deleted task.", from_status="deleted", to_status="active")

    # Lifecycle: completed -> active (or active -> active idempotent)
    cur = row.get("status")
    if cur == "active":
        # idempotent
        _log("ok", meta={"idempotent": True}, started=started)
        return {"task": row, "reopened": False, "idempotent": True}

    if cur != "completed":
        _log("error", meta={"code": "INVALID_TRANSITION", "from": cur, "to": "active"}, started=started)
        return _err("INVALID_TRANSITION", "Task status cannot transition to active from current state.", from_status=cur, to_status="active")

    now = _now()
    row = dict(row)
    row["status"] = "active"
    row["completed_at"] = None
    row["updated_at"] = now

    tasks[idx] = row
    _save("tasks.json", tasks)

    _log("ok", meta={"reopened": True}, started=started)
    return {"task": row, "reopened": True}

def get_tasks_by_filter(account_id, filter, limit=None, cursor=None, sort=None, sort_direction=None, include_completed=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, meta=None, started=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = None
            if started is not None:
                latency_ms = int((time.time() - started) * 1000)
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "get-tasks-by-filter",
                "account_id": account_id,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    started = time.time()

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id or ""):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "account_id"}, started=started)
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")

    if not isinstance(filter, str) or len(filter.strip()) < 1:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter"}, started=started)
        return _err("VALIDATION_ERROR", "filter must be a non-empty string.", field="filter")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "limit"}, started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "cursor"}, started=started)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.", field="cursor")

    if sort is None:
        sort = "created_at"
    if sort not in ("due_date", "priority", "created_at", "order"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort"}, started=started)
        return _err("VALIDATION_ERROR", "sort must be one of: due_date, priority, created_at, order.", field="sort")

    if sort_direction is None:
        sort_direction = "asc"
    if sort_direction not in ("asc", "desc"):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "sort_direction"}, started=started)
        return _err("VALIDATION_ERROR", "sort_direction must be 'asc' or 'desc'.", field="sort_direction")

    if include_completed is None:
        include_completed = False
    if not isinstance(include_completed, bool):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "include_completed"}, started=started)
        return _err("VALIDATION_ERROR", "include_completed must be a boolean.", field="include_completed")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", meta={"code": "NOT_FOUND", "entity": "todoist_accounts"}, started=started)
        return _err("NOT_FOUND", "Account not found.", entity="todoist_accounts", id=account_id)
    if acct.get("status") in ("revoked", "disabled"):
        _log("error", meta={"code": "UNAUTHORIZED"}, started=started)
        return _err("UNAUTHORIZED", "Account is not authorized to read in its current status.", account_status=acct.get("status"))

    tasks = _load("tasks.json")
    if not isinstance(tasks, list):
        tasks = []

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    active_project_ids = {p.get("id") for p in projects if p.get("account_id") == account_id and p.get("status") != "deleted"}

    def _parse_cursor(cur):
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    def _make_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    offset = 0
    if cursor is not None:
        offset = _parse_cursor(cursor)
        if offset is None:
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "cursor"}, started=started)
            return _err("VALIDATION_ERROR", "cursor is invalid or expired.", field="cursor")

    # Filter translation (safe subset)
    f = filter.strip()
    lowered = f.lower()

    # Collect predicates combined by AND only; if OR/parentheses present, treat as unsupported
    unsupported_tokens = (" or ", "||", "|", "(", ")", "!", "not ")
    if any(tok in lowered for tok in unsupported_tokens):
        # Fallback not available offline; behave as "cannot safely parse"
        _log("error", meta={"code": "VALIDATION_ERROR", "reason": "unsupported_filter"}, started=started)
        return _err("VALIDATION_ERROR", "Filter expression cannot be safely parsed by this server.", reason="unsupported_filter")

    # Split on '&'
    parts = [p.strip() for p in re.split(r"\s*&\s*", f) if p.strip()]

    want_priority = None  # int 1..4
    want_project_local_id = None
    want_label = None
    want_status_set = None  # set of statuses
    want_text_contains = None
    want_due_today = False
    want_overdue = False

    # helper: match project by name (active only)
    def _project_id_by_name(name):
        name_l = name.strip().lower()
        for p in projects:
            if p.get("account_id") == account_id and p.get("status") != "deleted" and isinstance(p.get("name"), str) and p["name"].strip().lower() == name_l:
                return p.get("id")
        return None

    for p in parts:
        pl = p.lower().strip()

        # priority token: p1..p4
        m = re.fullmatch(r"p([1-4])", pl)
        if m:
            want_priority = int(m.group(1))
            continue

        # label token: @work
        m = re.fullmatch(r"@(.+)", p.strip())
        if m:
            want_label = m.group(1).strip()
            if not want_label:
                _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter"}, started=started)
                return _err("VALIDATION_ERROR", "Label filter is invalid.", field="filter")
            continue

        # project token: #Project Name (Todoist style)
        m = re.fullmatch(r"#(.+)", p.strip())
        if m:
            proj_name = m.group(1).strip()
            if not proj_name:
                _log("error", meta={"code": "VALIDATION_ERROR", "field": "filter"}, started=started)
                return _err("VALIDATION_ERROR", "Project filter is invalid.", field="filter")
            pid = _project_id_by_name(proj_name)
            if pid is None:
                # filter matches nothing => empty result set
                want_project_local_id = "__no_such_project__"
            else:
                want_project_local_id = pid
            continue

        # status token
        if pl in ("completed", "done"):
            want_status_set = {"completed"}
            continue
        if pl in ("active", "open"):
            want_status_set = {"active"}
            continue

        # due tokens
        if pl == "today":
            want_due_today = True
            continue
        if pl == "overdue":
            want_overdue = True
            continue

        # quoted or plain text contains
        m = re.fullmatch(r'"(.+)"', p.strip())
        if m:
            want_text_contains = m.group(1)
            continue

        # unsupported token => fallback required, unavailable
        _log("error", meta={"code": "VALIDATION_ERROR", "reason": "unsupported_filter_token", "token": p}, started=started)
        return _err("VALIDATION_ERROR", "Filter expression contains unsupported token.", reason="unsupported_filter_token", token=p)

    # Apply account scoping + FK integrity: exclude tasks referencing deleted/nonexistent projects/sections when set.
    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []
    active_section_ids = {s.get("id") for s in sections if s.get("account_id") == account_id and s.get("status") != "deleted" and s.get("project_id") in active_project_ids}

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            # accept Z or offset
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_utc = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    today_start = datetime.datetime(now_utc.year, now_utc.month, now_utc.day, tzinfo=datetime.timezone.utc)
    tomorrow_start = today_start + datetime.timedelta(days=1)

    filtered = []
    for t in tasks:
        if t.get("account_id") != account_id:
            continue
        st = t.get("status")
        if st == "deleted":
            continue
        if (not include_completed) and st == "completed":
            continue

        # Optional status filter
        if want_status_set is not None and st not in want_status_set:
            continue

        # FK integrity checks
        pid = t.get("project_id")
        sid = t.get("section_id")
        if pid is not None and pid not in active_project_ids:
            continue
        if sid is not None and sid not in active_section_ids:
            continue

        if want_priority is not None and t.get("priority") != want_priority:
            continue

        if want_project_local_id is not None and pid != want_project_local_id:
            continue

        if want_label is not None:
            labels = t.get("labels")
            if not isinstance(labels, list):
                continue
            # case-insensitive match on stored labels (names or ids)
            wl = want_label.strip().lower()
            if all((not isinstance(x, str)) or (x.strip().lower() != wl) for x in labels):
                continue

        if want_text_contains is not None:
            content = t.get("content")
            if not isinstance(content, str) or want_text_contains.lower() not in content.lower():
                continue

        if want_due_today or want_overdue:
            due = _parse_dt(t.get("due_date"))
            if due is None:
                continue
            if want_due_today:
                if not (today_start <= due < tomorrow_start):
                    continue
            if want_overdue:
                if not (due < now_utc):
                    continue

        filtered.append(t)

    # Sort
    reverse = (sort_direction == "desc")

    def _sort_key(t):
        if sort == "priority":
            v = t.get("priority")
            return (v is None, v if isinstance(v, int) else 0, t.get("id"))
        if sort == "order":
            v = t.get("order")
            return (v is None, v if isinstance(v, int) else 0, t.get("id"))
        if sort == "due_date":
            d = _parse_dt(t.get("due_date"))
            # None due dates sorted last in asc, first in desc via reverse logic using tuple
            return (d is None, d.timestamp() if d else 0.0, t.get("id"))
        # created_at
        d = _parse_dt(t.get("created_at"))
        return (d is None, d.timestamp() if d else 0.0, t.get("id"))

    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log("ok", meta={"total": total, "returned": len(page), "has_more": has_more}, started=started)
    return {
        "tasks": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "sort_direction": sort_direction,
            "include_completed": include_completed,
            "filter": filter
        }
    }

def add_section(account_id, project_id, name, order=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")

    def _load(n):
