    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_id=None, meta=None, started=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            latency_ms = None
            if started is not None:
                latency_ms = int((time.time() - started) * 1000)
            logs.append({
                "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "add-section",
                "account_id": account_id,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": latency_ms,
                "timestamp": _now(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    def _new_id(prefix):
        # Non-ULID but conforms to pattern ^td..._[0-9A-Z]{2,}$
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(alphabet[b % 36] for b in secrets.token_bytes(12))

    started = time.time()

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id or ""):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "account_id"}, started=started)
        return _err("VALIDATION_ERROR", "account_id is invalid.", field="account_id")
    if not isinstance(project_id, str) or not re.match(r"^tdprj_[0-9A-Z]{2,}$", project_id or ""):
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "project_id"}, started=started)
        return _err("VALIDATION_ERROR", "project_id is invalid.", field="project_id")
    if not isinstance(name, str) or len(name.strip()) < 1:
        _log("error", meta={"code": "VALIDATION_ERROR", "field": "name"}, started=started)
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if order is not None:
        if not isinstance(order, int) or order < 0:
            _log("error", meta={"code": "VALIDATION_ERROR", "field": "order"}, started=started)
            return _err("VALIDATION_ERROR", "order must be an integer >= 0 when provided.", field="order")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if not acct:
        _log("error", meta={"code": "NOT_FOUND", "entity": "todoist_accounts"}, started=started)
        return _err("NOT_FOUND", "Account not found.", entity="todoist_accounts", id=account_id)
    if acct.get("status") in ("revoked", "disabled"):
        _log("error", meta={"code": "UNAUTHORIZED"}, started=started)
        return _err("UNAUTHORIZED", "Account is not authorized for modifications in its current status.", account_status=acct.get("status"))

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    proj = next((p for p in projects if p.get("id") == project_id and p.get("account_id") == account_id), None)
    if not proj:
        _log("error", meta={"code": "NOT_FOUND", "entity": "projects"}, started=started)
        return _err("NOT_FOUND", "Project not found.", entity="projects", id=project_id)
    if proj.get("status") == "deleted":
        _log("error", meta={"code": "INVALID_TRANSITION", "entity": "projects"}, started=started)
        return _err("INVALID_TRANSITION", "Cannot add a section to a deleted project.", project_status="deleted")
    if proj.get("status") not in ("active", "archived"):
        _log("error", meta={"code": "INVALID_TRANSITION", "entity": "projects"}, started=started)
        return _err("INVALID_TRANSITION", "Cannot add a section to project in its current status.", project_status=proj.get("status"))

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    # Constraint: unique(project_id, name) where status='active'
    for s in sections:
        if s.get("account_id") == account_id and s.get("project_id") == project_id and s.get("status") == "active":
            if isinstance(s.get("name"), str) and s["name"].strip().lower() == name.strip().lower():
                _log("error", meta={"code": "CONFLICT", "constraint": "unique(project_id,name)"}, started=started)
                return _err("CONFLICT", "An active section with this name already exists in the project.", constraint="unique(project_id,name)", project_id=project_id, name=name)

    # Create
    now = _now()
    new_row = {
        "id": _new_id("tdsec"),
        "account_id": account_id,
        "project_id": project_id,
        "todoist_section_id": _new_id("tsec_remote"),  # placeholder mirror id for offline enqueue simulation
        "name": name.strip(),
        "order": order,
        "status": "active",
        "created_at": now,
        "updated_at": now
    }

    # Constraint: unique(account_id, todoist_section_id)
    if any(s.get("account_id") == account_id and s.get("todoist_section_id") == new_row["todoist_section_id"] for s in sections):
        # extremely unlikely; regenerate a few times
        for _ in range(5):
            new_row["todoist_section_id"] = _new_id("tsec_remote")
            if not any(s.get("account_id") == account_id and s.get("todoist_section_id") == new_row["todoist_section_id"] for s in sections):
                break
        else:
            _log("error", meta={"code": "CONFLICT", "constraint": "unique(account_id,todoist_section_id)"}, started=started)
            return _err("CONFLICT", "Could not allocate a unique todoist_section_id.", constraint="unique(account_id,todoist_section_id)")

    sections.append(new_row)
    _save("sections.json", sections)

    _log("ok", meta={"section_id": new_row["id"]}, started=started)
    return {"section": new_row}

def get_section(account_id, section_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
