            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": now,
        }
        if meta is not None:
            entry["meta"] = meta
        logs.append(entry)
        _save("request_logs.json", logs)

    def _enforce_limits(credential_id=None):
        # If no logging collection exists, do nothing.
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        # Simple global per-account rate: 120 req/min; daily quota: 10k req/day
        def _parse_ts(s):
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        nowdt = datetime.datetime.utcnow()
        one_min_ago = nowdt - datetime.timedelta(seconds=60)
        day_ago = nowdt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reversed(logs):
            if r.get("service") != "todoist":
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("ts", ""))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
            if ts < day_ago:
                break
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # ---- validation ----
    if not isinstance(account_id, str) or re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id) is None:
        e = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        _log("error", meta=e)
        return e
    if not isinstance(section_id, str) or re.match(r"^tdsec_[0-9A-Z]{2,}$", section_id) is None:
        e = _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")
        _log("error", meta=e)
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", meta=limerr)
        return limerr

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        e = _err("NOT_FOUND", "Account not found.")
        _log("error", meta=e)
        return e
    if acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "Account is not active for this operation.", status=acct.get("status"))
        _log("error", meta=e)
        return e

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []
    sec = next((s for s in sections if s.get("id") == section_id), None)
    if sec is None or sec.get("account_id") != account_id:
        e = _err("NOT_FOUND", "Section not found.")
        _log("error", meta=e)
        return e

    # FK integrity: ensure referenced project not deleted (if present)
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    prj = next((p for p in projects if p.get("id") == sec.get("project_id") and p.get("account_id") == account_id), None)
    if prj is None or prj.get("status") == "deleted":
        e = _err("CONFLICT", "Section references a missing or deleted project.")
        _log("error", meta=e)
        return e

    _log("ok")
    return {"section": sec}

def get_sections(account_id, project_id, limit=None, cursor=None, include_deleted=None, sort=None, sort_direction=None, **_extra):
