            "ts": now,
        }
        if meta is not None:
            entry["meta"] = meta
        logs.append(entry)
        _save("request_logs.json", logs)

    def _enforce_limits():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        def _parse_ts(s):
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        nowdt = datetime.datetime.utcnow()
        one_min_ago = nowdt - datetime.timedelta(seconds=60)
        day_ago = nowdt - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reversed(logs):
            if r.get("service") != "todoist":
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("ts", ""))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
            if ts < day_ago:
                break
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # ---- validation ----
    if not isinstance(account_id, str) or re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id) is None:
        e = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        _log("error", meta=e)
        return e
    if not isinstance(project_id, str) or re.match(r"^tdprj_[0-9A-Z]{2,}$", project_id) is None:
        e = _err("VALIDATION_ERROR", "project_id is malformed.", field="project_id")
        _log("error", meta=e)
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
        _log("error", meta=e)
        return e
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) < 1:
            e = _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")
            _log("error", meta=e)
            return e
    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        e = _err("VALIDATION_ERROR", "include_deleted must be boolean.", field="include_deleted")
        _log("error", meta=e)
        return e
    if sort is None:
        sort = "order"
    if sort not in ("order", "name", "created_at", "updated_at"):
        e = _err("VALIDATION_ERROR", "Unsupported sort.", field="sort")
        _log("error", meta=e)
        return e
    if sort_direction is None:
        sort_direction = "asc"
    if sort_direction not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Unsupported sort_direction.", field="sort_direction")
        _log("error", meta=e)
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", meta=limerr)
        return limerr

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        e = _err("NOT_FOUND", "Account not found.")
        _log("error", meta=e)
        return e
    if acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "Account is not active for this operation.", status=acct.get("status"))
        _log("error", meta=e)
        return e

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    prj = next((p for p in projects if p.get("id") == project_id and p.get("account_id") == account_id), None)
    if prj is None or prj.get("status") == "deleted":
        e = _err("NOT_FOUND", "Project not found.")
        _log("error", meta=e)
        return e

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []
    rows = [s for s in sections if s.get("account_id") == account_id and s.get("project_id") == project_id]
    if not include_deleted:
        rows = [s for s in rows if s.get("status") != "deleted"]

    # cursor is base64 of {"offset": int}
    offset = 0
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            payload = json.loads(raw)
            if not isinstance(payload, dict) or not isinstance(payload.get("offset"), int) or payload["offset"] < 0:
                raise ValueError("bad cursor")
            offset = payload["offset"]
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            _log("error", meta=e)
            return e

    def _key(s):
        v = s.get(sort)
        if sort == "order":
            # nulls last in asc, first in desc (stable)
            return (v is None, v if v is not None else 0, s.get("id"))
        if sort in ("created_at", "updated_at"):
            return (v is None, v or "", s.get("id"))
        if sort == "name":
            return ((v or "").lower(), s.get("id"))
        return (s.get("id"),)

    reverse = (sort_direction == "desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_payload = {"offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(next_payload).encode("utf-8")).decode("utf-8")

    _log("ok", meta={"returned": len(page), "total": total})
    return {
        "sections": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

