    if order is not None and sec.get("order") != order:
        sec["order"] = order
        changed = True

    if not changed:
        # Idempotent: still a success, but ensure we did not claim mutation without effect.
        _log("ok", meta={"idempotent": True})
        return {"section": sec}

    sec["updated_at"] = now
    sections[idx] = sec
    _save("sections.json", sections)

    _log("ok", meta={"updated": True})
    return {"section": sec}

def delete_section(account_id, section_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": "rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "service": "todoist",
            "endpoint": "delete-section",
            "account_id": account_id,
            "credential_id": None,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": now,
        }
        if meta is not None:
            entry["meta"] = meta
        logs.append(entry)
        _save("request_logs.json", logs)

    def _enforce_limits():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        def _parse_ts(s):
            try:
                if s.endswith("Z"):
                    s = s[:-1]
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        nowu = datetime.datetime.utcnow()
        one_min_ago = nowu - datetime.timedelta(seconds=60)
        day_ago = nowu - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for r in reversed(logs):
            if r.get("service") != "todoist":
                continue
            if r.get("account_id") != account_id:
                continue
            ts = _parse_ts(r.get("ts", ""))
            if ts is None:
                continue
            if ts >= one_min_ago:
                per_min += 1
            if ts >= day_ago:
                per_day += 1
            if ts < day_ago:
                break
        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        if per_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    # ---- validation ----
    if not isinstance(account_id, str) or re.match(r"^tdacct_[0-9A-Z]{2,}$", account_id) is None:
        e = _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")
        _log("error", meta=e)
        return e
    if not isinstance(section_id, str) or re.match(r"^tdsec_[0-9A-Z]{2,}$", section_id) is None:
        e = _err("VALIDATION_ERROR", "section_id is malformed.", field="section_id")
        _log("error", meta=e)
        return e

    limerr = _enforce_limits()
    if limerr:
        _log("error", meta=limerr)
        return limerr

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        e = _err("NOT_FOUND", "Account not found.")
        _log("error", meta=e)
        return e
    if acct.get("status") != "active":
        e = _err("UNAUTHORIZED", "Account is not active for this operation.", status=acct.get("status"))
        _log("error", meta=e)
        return e

    sections = _load("sections.json")
    if not isinstance(sections, list):
        sections = []

    idx = None
    for i, s in enumerate(sections):
        if s.get("id") == section_id:
            idx = i
            break
    if idx is None or sections[idx].get("account_id") != account_id:
        e = _err("NOT_FOUND", "Section not found.")
        _log("error", meta=e)
        return e

    sec = sections[idx]
    if sec.get("status") == "deleted":
        e = _err("CONFLICT", "Section is already deleted.")
        _log("error", meta=e)
        return e

    # FK integrity: project must exist and not be deleted (still required to operate within mirror)
    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    prj = next((p for p in projects if p.get("id") == sec.get("project_id") and p.get("account_id") == account_id), None)
    if prj is None or prj.get("status") == "deleted":
        e = _err("CONFLICT", "Section references a missing or deleted project.")
        _log("error", meta=e)
        return e

    # Soft delete
    sec["status"] = "deleted"
    sec["updated_at"] = now
    sections[idx] = sec
    _save("sections.json", sections)

    _log("ok", meta={"deleted": True})
    return {"section": sec, "meta": {"deleted": True}}

