    # unique(account_id, todoist_comment_id)
    if any(isinstance(c, dict) and c.get("account_id") == account_id and c.get("todoist_comment_id") == todoist_comment_id for c in comments):
        _log("error", "CONFLICT", "Comment already exists for this account.")
        return _err("CONFLICT", "Comment already exists for this account.", todoist_comment_id=todoist_comment_id)

    comments.append(row)
