def get_comments(account_id, task_id=None, project_id=None, status=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_s, err_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("="),
            "endpoint": "get-comments",
            "account_id": account_id,
            "status": status_s,
            "error_code": err_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _is_str(x): return isinstance(x, str)
    def _valid_id(prefix, s):
        return _is_str(s) and s.startswith(prefix) and len(s) >= len(prefix) + 6

    if not _is_str(account_id) or not account_id:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string", field="account_id")

    if task_id is not None and not _is_str(task_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "task_id must be a string", field="task_id")
    if project_id is not None and not _is_str(project_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id must be a string", field="project_id")

    if task_id and project_id:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide at most one of task_id or project_id", field="target")

    if task_id and not _valid_id("tdtsk_", task_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed task_id", field="task_id")
    if project_id and not _valid_id("tdprj_", project_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed project_id", field="project_id")

    if status is not None:
        if not _is_str(status) or status not in ("active", "deleted"):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "deleted"])

    if sort is None:
        sort = "-created_at"
    if not _is_str(sort) or sort not in ("created_at", "-created_at"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=["created_at", "-created_at"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if cursor is not None and not _is_str(cursor):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Decode cursor as integer offset (opaque to caller)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Account not found")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)
    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account connection is not active", status=acct.get("status"))

    projects = _load("projects.json")
    tasks = _load("tasks.json")
    comments = _load("comments.json")
    if not isinstance(projects, list): projects = []
    if not isinstance(tasks, list): tasks = []
    if not isinstance(comments, list): comments = []

    # Validate target existence and ownership (if provided)
    if project_id:
        prj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id and p.get("account_id") == account_id), None)
        if not prj or prj.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Project not found", project_id=project_id)
    if task_id:
        tsk = next((t for t in tasks if isinstance(t, dict) and t.get("id") == task_id and t.get("account_id") == account_id), None)
        if not tsk or tsk.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Task not found", task_id=task_id)

    # Filter by account scope
    rows = [c for c in comments if isinstance(c, dict) and c.get("account_id") == account_id]

    if task_id:
        rows = [c for c in rows if c.get("task_id") == task_id]
    if project_id:
        rows = [c for c in rows if c.get("project_id") == project_id]
    if status:
        rows = [c for c in rows if c.get("status") == status]
    else:
        # Default: only active
        rows = [c for c in rows if c.get("status") == "active"]

    reverse = (sort == "-created_at")
    def _key(c):
        v = c.get("created_at")
        return v if isinstance(v, str) else ""
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("ascii").rstrip("=")

    _log("ok")
    return {
        "comments": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

