        return _err("VALIDATION_ERROR", "content must be a non-empty string", field="content")

    if attachment is not None and not isinstance(attachment, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "attachment must be an object", field="attachment")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Account not found")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Account not found", account_id=account_id)
    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account connection is not active", status=acct.get("status"))

    comments = _load("comments.json")
    if not isinstance(comments, list):
        comments = []

    idx = None
    for i, c in enumerate(comments):
        if isinstance(c, dict) and c.get("id") == comment_id and c.get("account_id") == account_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Comment not found", comment_id=comment_id)

    c = comments[idx]
    if c.get("status") == "deleted":
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Deleted comments cannot be updated", comment_id=comment_id)

    changed = False
    if content is not None and content != c.get("content"):
        c["content"] = content
        changed = True
    if attachment is not None:
        # Replacement payload (can be {})
        if attachment != c.get("attachment"):
            c["attachment"] = attachment
            changed = True

    if not changed:
        # Idempotent: no changes requested vs stored
        _log("ok")
        return {"comment": c}

    c["updated_at"] = now
    comments[idx] = c
    _save("comments.json", comments)

    _log("ok")
    return {"comment": c}

