    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _enc_cursor(payload_dict):
        raw = json.dumps(payload_dict, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _dec_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return "INVALID"
        pad = "=" * ((4 - (len(cur) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            return obj
        except Exception:
            return "INVALID"

    # Validate
