            continue
        if c.get("account_id") != account_id:
            continue
        if c.get("task_id") != task_id:
            continue
        if c.get("status") != status:
            continue
        rows.append(c)

    reverse = (sort == "-created_at")
    rows.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or ""), reverse=reverse)

