            "account_id": account_id,
            "task_id": task_id,
            "status": status,
            "sort": sort,
            "offset": start + limit
        })

    _log("ok")
    return {
        "comments": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": bool(next_cursor)
        }
    }

