        _log("error", "VALIDATION_ERROR", "Malformed account_id.")
        return _err("VALIDATION_ERROR", "Malformed account_id.", field="account_id")
    if not isinstance(task_id, str) or not re.match(r"^tdtsk_[0-9A-Z]{2,}$", task_id or ""):
        _log("error", "VALIDATION_ERROR", "Malformed task_id.")
        return _err("VALIDATION_ERROR", "Malformed task_id.", field="task_id")
    if not isinstance(label_id, str) or not re.match(r"^tdlbl_[0-9A-Z]{2,}$", label_id or ""):
        _log("error", "VALIDATION_ERROR", "Malformed label_id.")
        return _err("VALIDATION_ERROR", "Malformed label_id.", field="label_id")

