    if tidx is None:
        _log("error", "NOT_FOUND", "Task not found for this account.")
        return _err("NOT_FOUND", "Task not found for this account.", task_id=task_id)
    if tasks[tidx].get("status") == "deleted":
        _log("error", "CONFLICT", "Cannot modify labels for a deleted task.")
        return _err("CONFLICT", "Cannot modify labels for a deleted task.", task_id=task_id)

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []
    lrow = next((l for l in labels if isinstance(l, dict) and l.get("id") == label_id and l.get("account_id") == account_id), None)
    if lrow is None:
        _log("error", "NOT_FOUND", "Label not found for this account.")
        return _err("NOT_FOUND", "Label not found for this account.", label_id=label_id)
    if lrow.get("status") == "deleted":
        _log("error", "CONFLICT", "Label is deleted.")
        return _err("CONFLICT", "Label is deleted.", label_id=label_id)

    task_labels = tasks[tidx].get("labels")
    if not isinstance(task_labels, list):
        task_labels = []
    # store label name (canonical) in tasks.labels, matching business rule approach
    label_name = lrow.get("name")
    if not isinstance(label_name, str) or not label_name.strip():
        _log("error", "CONFLICT", "Label record has no usable name to attach.")
        return _err("CONFLICT", "Label record has no usable name to attach.", label_id=label_id)

    canon = label_name.strip()
    if any(isinstance(x, str) and x.casefold() == canon.casefold() for x in task_labels):
        _log("error", "CONFLICT", "Label is already present on the task.")
        return _err("CONFLICT", "Label is already present on the task.", task_id=task_id, label=canon)

    task_labels.append(canon)
    tasks[tidx]["labels"] = task_labels
    tasks[tidx]["updated_at"] = _now_iso()
    _save("tasks.json", tasks)

    _log("success", None, None)
    return {"task": tasks[tidx]}

