def update_label(account_id, label_id, name=None, color=None, is_favorite=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(account_id, str) or not account_id.strip():
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string")
    if not isinstance(label_id, str) or not label_id.strip():
        return _err("VALIDATION_ERROR", "label_id must be a non-empty string")
    if not re.match(r"^tdacct_[0-9A-Z]{10,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed")
    if not re.match(r"^tdlbl_[0-9A-Z]{10,}$", label_id):
        return _err("VALIDATION_ERROR", "label_id is malformed")

    updatable_present = False
    if name is not None:
        updatable_present = True
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string when provided")
        if not name.strip():
            return _err("VALIDATION_ERROR", "name must not be empty")
    if color is not None:
        updatable_present = True
        if not isinstance(color, str):
            return _err("VALIDATION_ERROR", "color must be a string when provided")
        if not color.strip():
            return _err("VALIDATION_ERROR", "color must not be empty when provided")
        # Schema does not provide the palette; validate as a reasonable Todoist color identifier
        if not re.match(r"^[a-z0-9_]+$", color.strip()):
            return _err("VALIDATION_ERROR", "color is invalid (expected Todoist color identifier)")
    if is_favorite is not None:
        updatable_present = True
        if not isinstance(is_favorite, bool):
            return _err("VALIDATION_ERROR", "is_favorite must be a boolean when provided")

    if not updatable_present:
        return _err("VALIDATION_ERROR", "No updatable fields supplied; provide at least one of name, color, is_favorite")

    accounts = _load("todoist_accounts.json")
    labels = _load("labels.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        return _err("NOT_FOUND", "account_id not found")
    if acct.get("status") != "active":
        return _err("UNAUTHORIZED", "Not authorized to manage labels for this account", account_status=acct.get("status"))

    idx = None
    for i, r in enumerate(labels):
        if r.get("id") == label_id and r.get("account_id") == account_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "label_id not found under account")

    lab = labels[idx]
    if lab.get("status") == "deleted":
        return _err("CONFLICT", "Cannot update a deleted label", label=lab)

    # Enforce label name case-insensitive uniqueness per account among active labels
    if name is not None:
        new_name = name.strip()
        new_name_key = new_name.casefold()
        for r in labels:
            if r.get("account_id") != account_id:
                continue
            if r.get("id") == label_id:
                continue
            if r.get("status") != "active":
                continue
            existing = (r.get("name") or "").strip()
            if existing and existing.casefold() == new_name_key:
                return _err("CONFLICT", "An active label with the same name already exists (case-insensitive)", conflicting_label_id=r.get("id"))

    updated = dict(lab)
    if name is not None:
        updated["name"] = name.strip()
    if color is not None:
        updated["color"] = color.strip()
    if is_favorite is not None:
        updated["is_favorite"] = is_favorite
    updated["updated_at"] = now

    # Constraints sanity
    if not isinstance(updated.get("is_favorite"), bool):
        return _err("VALIDATION_ERROR", "is_favorite must be boolean")
    if not isinstance(updated.get("is_shared"), bool):
        return _err("VALIDATION_ERROR", "is_shared must be boolean")
    if not isinstance(updated.get("name"), str) or not updated["name"].strip():
        return _err("VALIDATION_ERROR", "name must not be empty")

    labels[idx] = updated
    _save("labels.json", labels)
    return {"label": labels[idx]}

