def get_labels(account_id, status=None, is_shared=None, is_favorite=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if not isinstance(account_id, str) or not account_id.strip():
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string")
    if not re.match(r"^tdacct_[0-9A-Z]{10,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed")

    if status is not None:
        if status not in ("active", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, deleted")
    if is_shared is not None and not isinstance(is_shared, bool):
        return _err("VALIDATION_ERROR", "is_shared must be a boolean when provided")
    if is_favorite is not None and not isinstance(is_favorite, bool):
        return _err("VALIDATION_ERROR", "is_favorite must be a boolean when provided")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit <= 0 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if sort is None:
        sort = "name"
    if sort not in ("name", "created_at", "updated_at"):
        return _err("VALIDATION_ERROR", "sort must be one of: name, created_at, updated_at")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        # opaque cursor: base64url("v1:<start>")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            if not raw.startswith("v1:"):
                return _err("VALIDATION_ERROR", "cursor is invalid")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                return _err("VALIDATION_ERROR", "cursor is invalid")
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return _err("VALIDATION_ERROR", "cursor is invalid")

    accounts = _load("todoist_accounts.json")
    labels = _load("labels.json")

    acct = next((a for a in accounts if a.get("id") == account_id), None)
    if acct is None:
        return _err("NOT_FOUND", "account_id not found")
    if acct.get("status") not in ("active", "error", "disabled", "revoked"):
        return _err("UNAUTHORIZED", "Not authorized to read labels for this account", account_status=acct.get("status"))

    # Filter to account scope
    rows = [r for r in labels if r.get("account_id") == account_id]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if is_shared is not None:
        rows = [r for r in rows if r.get("is_shared") is is_shared]
    if is_favorite is not None:
        rows = [r for r in rows if r.get("is_favorite") is is_favorite]

    total = len(rows)

    # Sort
    reverse = (order == "desc")
    def _key(r):
        v = r.get(sort)
        if sort == "name":
            return ((v or "").casefold(), r.get("id") or "")
        return (v or "", r.get("id") or "")
    rows.sort(key=_key, reverse=reverse)

    # Paginate
    if start > total:
        # Cursor beyond end: empty page, no error
        page = []
        has_more = False
        next_cursor = None
    else:
        page = rows[start:start + limit]
        has_more = (start + limit) < total
        next_cursor = None
        if has_more:
            raw = f"v1:{start + limit}".encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    return {
        "labels": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order
        }
    }

def get_shared_labels(account_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((str(time.time_ns()) + account_id).encode("utf-8")).hexdigest()[:24],
            "endpoint": "get-shared-labels",
            "account_id": account_id if isinstance(account_id, str) else None,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            **extra
        })
        _save("request_logs.json", logs)

    def _validate_ulid_like(v, prefix):
        return isinstance(v, str) and v.startswith(prefix) and len(v) >= len(prefix) + 6

    # Validate inputs
    if not _validate_ulid_like(account_id, "tdacct_"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")

    if status is not None and status not in ("active", "deleted"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    if sort is None:
        sort = "name"
    if sort not in ("name", "created_at", "updated_at"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "order is invalid", field="order")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    # Resolve ambient authorization context: must be able to operate on some active account.
    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "account_id not found", field="account_id")

    # Ambient auth rule: if there is no viable active account at all, treat as unauthorized.
    # Otherwise, allow access to the requested account only if it is itself usable (non-revoked).
    any_usable = any(isinstance(a, dict) and a.get("status") in ("active", "error", "disabled") for a in accounts)
    if not any_usable:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated Todoist account context is available")

    if acct.get("status") == "revoked":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account token is revoked")

    # Rate limiting / quota (best-effort based on request_logs.json if present)
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # Simple per-account rate limit: 120 requests/minute
    try:
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        recent = 0
        for r in logs[::-1]:
            if not isinstance(r, dict): 
                continue
            if r.get("account_id") != account_id:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                except ValueError:
                    continue
                if dt >= cutoff:
                    recent += 1
        if recent >= 120:
            _log("RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=120, retry_after_seconds=60)
    except Exception:
        # Do not fail request due to log parsing issues
        pass

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []

    # Filter to shared labels for this account
    rows = []
    for lb in labels:
        if not isinstance(lb, dict):
            continue
        if lb.get("account_id") != account_id:
            continue
        if lb.get("is_shared") is not True:
            continue
        if status is not None and lb.get("status") != status:
            continue
        rows.append(lb)

    # Sort
    def _key(v):
        x = v.get(sort)
        if sort == "name":
            return ("" if x is None else str(x).casefold())
        return "" if x is None else str(x)
    reverse = (order == "desc")
    rows.sort(key=_key, reverse=reverse)

    # Cursor is opaque; implement as base64 JSON {"offset": n, "sig": "..."}.
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj or not isinstance(obj["offset"], int) or obj["offset"] < 0:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
            # account binding
            if obj.get("account_id") != account_id:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor does not match account", field="cursor")
            offset = obj["offset"]
        except (ValueError, json.JSONDecodeError, UnicodeDecodeError):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_cursor = None
    if offset + limit < total:
        payload = {"account_id": account_id, "offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("OK")
    return {
        "shared_labels": page,
        "account_id": account_id,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
        "sort": sort,
        "order": order
    }

