            row = lb
            break

    if row is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "label_id not found under account", field="label_id")

    if row.get("is_shared") is not True:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label_id is not a shared label", field="label_id")

    if row.get("status") == "deleted":
        _log("CONFLICT")
        return _err("CONFLICT", "Shared label is already removed/deleted", field="label_id")

