def rename_shared_label(account_id, label_id, name, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((str(time.time_ns()) + account_id + label_id).encode("utf-8")).hexdigest()[:24],
            "endpoint": "rename-shared-label",
            "account_id": account_id if isinstance(account_id, str) else None,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            **extra
        })
        _save("request_logs.json", logs)

    def _validate_ulid_like(v, prefix):
        return isinstance(v, str) and v.startswith(prefix) and len(v) >= len(prefix) + 6

    if not _validate_ulid_like(account_id, "tdacct_"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")
    if not _validate_ulid_like(label_id, "tdlbl_"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label_id is malformed", field="label_id")

    if not isinstance(name, str):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a string", field="name")
    new_name = name.strip()
    if not new_name:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must not be empty", field="name")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if acct is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "account_id not found", field="account_id")

    any_usable = any(isinstance(a, dict) and a.get("status") in ("active", "error", "disabled") for a in accounts)
    if not any_usable:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated Todoist account context is available")
    if acct.get("status") == "revoked":
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Account token is revoked")

    labels = _load("labels.json")
    if not isinstance(labels, list):
        labels = []

    idx = None
    row = None
    for i, lb in enumerate(labels):
        if isinstance(lb, dict) and lb.get("id") == label_id and lb.get("account_id") == account_id:
            idx = i
            row = lb
            break

    if row is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "label_id not found under account", field="label_id")

    if row.get("is_shared") is not True:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "label_id is not a shared label", field="label_id")

    if row.get("status") == "deleted":
        _log("CONFLICT")
        return _err("CONFLICT", "Shared label is removed/deleted", field="label_id")

    # Enforce case-insensitive uniqueness among active labels (constraint)
    canon = new_name.casefold()
    for lb in labels:
        if not isinstance(lb, dict):
            continue
        if lb.get("account_id") != account_id:
            continue
        if lb.get("status") != "active":
            continue
        if lb.get("id") == label_id:
            continue
        if isinstance(lb.get("name"), str) and lb["name"].strip().casefold() == canon:
            _log("CONFLICT")
            return _err("CONFLICT", "An active label with that name already exists", field="name")

    updated = dict(row)
    updated["name"] = new_name
    updated["updated_at"] = now
    labels[idx] = updated
    _save("labels.json", labels)

    _log("OK")
    return {"shared_label": updated}

def get_whoami(include_quota=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0191000" if __import__("os").path.isdir("./environment_mix/0191000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log(status_code, account_id=None, extra=None):
        extra = extra or {}
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + hashlib.sha256((str(time.time_ns()) + (account_id or "")).encode("utf-8")).hexdigest()[:24],
            "endpoint": "get-whoami",
            "account_id": account_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
            **extra
        })
        _save("request_logs.json", logs)

    if include_quota is None:
        include_quota = True
    if not isinstance(include_quota, bool):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "include_quota must be boolean", field="include_quota")

    accounts = _load("todoist_accounts.json")
    if not isinstance(accounts, list):
        accounts = []

    # Ambient identity: pick a usable authenticated account context (prefer active).
    usable = [a for a in accounts if isinstance(a, dict) and a.get("status") in ("active", "error", "disabled")]
    usable.sort(key=lambda a: (0 if a.get("status") == "active" else 1, "" if a.get("updated_at") is None else str(a.get("updated_at"))), reverse=False)
    if not usable:
        _log("UNAUTHORIZED", account_id=None)
        return _err("UNAUTHORIZED", "Account token is missing/invalid")

    acct = usable[0]
    account_id = acct.get("id")

    # In this datastore there is no per-token permission model; if account exists, allow identity details.
    # Quota/rate: derive from request_logs if available.
    out = {
        "account": acct,
        "scopes": acct.get("scopes") if isinstance(acct.get("scopes"), list) else [],
    }

    if include_quota:
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []

        # Rate policy (same as other tools): 120 req/min per account.
        rate_limit_per_minute = 120
        window_seconds = 60
        cutoff = now_dt - datetime.timedelta(seconds=window_seconds)
        used = 0
        for r in logs[::-1]:
            if not isinstance(r, dict):
                continue
            if r.get("account_id") != account_id:
                continue
            ts = r.get("timestamp")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                except ValueError:
                    continue
                if dt >= cutoff:
                    used += 1

        # Next reset: start of next minute window relative to now.
        reset_at = (now_dt + datetime.timedelta(seconds=window_seconds)).replace(microsecond=0).isoformat() + "Z"
        remaining = max(0, rate_limit_per_minute - used)

        out["quota"] = {
            "rate_limit": {
                "limit_per_minute": rate_limit_per_minute,
                "window_seconds": window_seconds,
                "used_in_window": used,
                "remaining_in_window": remaining,
                "reset_at": reset_at
            }
        }

    _log("OK", account_id=account_id)
    return out
